function groupBy<T, K extends string | number | symbol>(arr: T[], keyFn: (v: T) => K): Record<string, T[]> {
  const out: Record<string, T[]> = {};
  for (const v of arr) { const k = String(keyFn(v)); (out[k] ??= []).push(v); }
  return out;
}
